};

// Example with std::string
std::string& append(const std::string& str);
std::string& append(const char* s);
std::string& append(size_t n, char c);

code_example:
#include <iostream>
#include <string>

int main() {
    std::string s = "Hello";
    s.append(" World"); // Appends C-string
    s.append(3, '!');     // Appends three exclamation marks
    std::cout << s << std::endl; // Output: Hello World!!!
    return 0;
}
